import type {TrackerSelectGroup, TrackerSelectItemValueBase} from '../../TrackerSelect/types';

/**
 * Splits groups by item.tags into separate tag sections.
 * Items with no tags remain in their original group.
 * Items with tags are duplicated into tag-specific sub-groups.
 */
export function splitGroupsByTags<Value extends TrackerSelectItemValueBase>(
    groups: TrackerSelectGroup<Value>[],
): TrackerSelectGroup<Value>[] {
    const taggedGroupsMap = new Map<string, TrackerSelectGroup<Value>[]>();
    const groupsWithoutTaggedItems: TrackerSelectGroup<Value>[] = [];

    for (const group of groups) {
        const items = Object.values(
            group.items ?? {},
        ) as TrackerSelectGroup<Value>['items'][string][];

        const currentGroupItemsByTag = new Map<string, TrackerSelectGroup<Value>['items']>();
        const itemsWithoutTag: TrackerSelectGroup<Value>['items'] = {};

        for (const item of items) {
            const tags = item.tags ?? [];

            if (!tags.length) {
                itemsWithoutTag[item.id] = item;
            }

            for (const tag of tags) {
                const itemsWithTag = currentGroupItemsByTag.get(tag) ?? {};
                itemsWithTag[item.id] = item;
                currentGroupItemsByTag.set(tag, itemsWithTag);
            }
        }

        for (const [tag, itemsWithTag] of currentGroupItemsByTag) {
            const groupsByTag = taggedGroupsMap.get(tag) ?? [];
            groupsByTag.push({
                ...group,
                tag,
                items: itemsWithTag,
            });
            taggedGroupsMap.set(tag, groupsByTag);
        }

        if (Object.keys(itemsWithoutTag).length > 0) {
            groupsWithoutTaggedItems.push({
                ...group,
                items: itemsWithoutTag,
            });
        }
    }

    const tagged: TrackerSelectGroup<Value>[] = [];

    for (const [tag, values] of taggedGroupsMap) {
        tagged.push({id: tag, type: 'named', name: tag, items: {}}, ...values);
    }

    return [...groupsWithoutTaggedItems, ...tagged];
}
